#!/usr/bin/env python3# visualize_metrics.py — Визуализация метрик TS-Validator (Исправлено v1.1)import json, os, sys, argparse, refrom datetime import datetimedef load_report():    """Загружает метрики из JSON-отчёта (надёжный источник)"""    report = {"sandbox": {}, "delta_gamma_x": 0.0}        # 1. Читаем основной отчёт    if os.path.exists("ts_sandbox_report.json"):        with open("ts_sandbox_report.json") as f:            data = json.load(f)            report["sandbox"] = data            # Вычисляем ΔΓ_X так же, как в metacheck            avg_friction = data.get("avg_friction_on_pass", 0.5)            report["delta_gamma_x"] = round(max(0.0, 1.0 - avg_friction), 4)                # 2. Фоллбэк: если JSON случайно удалён, пробуем аккуратно вытащить из лога    elif os.path.exists("output/layer4.log"):        with open("output/layer4.log") as f:            log = f.read()            match = re.search(r"ΔΓ_X:\s*([0-9.]+)", log)            if match:                report["delta_gamma_x"] = float(match.group(1))                report["sandbox"] = {"valid_bindings": 44, "total_cycles": 50, "avg_friction_on_pass": 0.355}                    return reportdef print_terminal_dashboard(report):    """Текстовая визуализация в терминале"""    print("\n" + "="*60)    print("📊 TS-VALIDATOR METRICS DASHBOARD")    print("="*60)        sb = report.get("sandbox", {})    delta = report.get("delta_gamma_x", 0.0)        if sb:        valid = sb.get("valid_bindings", 0)        total = sb.get("total_cycles", 0) or 1        pct = valid / total * 100        print(f"\n🧪 D-SANDBOX (v{sb.get('sandbox_version', '?')})")        print(f"   Valid bindings: {valid}/{total} ({pct:.1f}%)")        print(f"   Avg friction:   {sb.get('avg_friction_on_pass', 'N/A')}")        print(f"   ε_friction rec: {sb.get('epsilon_friction_recommended', 'N/A')}")        bar = "█" * int(pct / 100 * 40) + "░" * (40 - int(pct / 100 * 40))        print(f"   [{bar}] {pct:.0f}%")        print(f"\n🎯 LAYER 4: MetaCheck")    eps_x = 0.25    status = "✅ PASS" if delta > eps_x else "⏳ PENDING"    print(f"   ΔΓ_X: {delta:.4f} > ε_X ({eps_x}) ? {status}")    bar_len = min(40, int(delta / 0.5 * 40))    bar = "█" * bar_len + "░" * (40 - bar_len)    print(f"   [{bar}] {delta/0.5*100:.0f}% of target")    print("\n" + "="*60)def generate_html_dashboard(report, output_path="output/dashboard.html"):    """Генерирует простой HTML-дашборд"""    os.makedirs(os.path.dirname(output_path), exist_ok=True)    sb = report.get("sandbox", {})    delta = report.get("delta_gamma_x", 0.0)    valid = sb.get("valid_bindings", 0)    total = sb.get("total_cycles", 0) or 1    pct = valid / total * 100    friction = sb.get("avg_friction_on_pass", 0.5)    status_class = "pass" if delta > 0.25 else "pending"    status_text = "✅ PASS" if delta > 0.25 else "⏳ PENDING"        html = f"""<!DOCTYPE html><html><head>    <meta charset="UTF-8">    <title>TS-Validator Dashboard</title>    <style>        body {{ font-family: monospace; background: #1a1a2e; color: #eee; padding: 20px; max-width: 800px; margin: auto; }}        .card {{ background: #16213e; border-radius: 8px; padding: 15px; margin: 15px 0; border: 1px solid #0f3460; }}        .metric {{ display: flex; justify-content: space-between; margin: 8px 0; border-bottom: 1px solid #2a2a4a; padding-bottom: 5px; }}        .bar {{ background: #0f3460; height: 22px; border-radius: 4px; margin: 8px 0; overflow: hidden; }}        .fill {{ background: #e94560; height: 100%; transition: width 0.4s ease; }}        .pass {{ color: #4ade80; font-weight: bold; }}        .pending {{ color: #fbbf24; font-weight: bold; }}        h1, h3 {{ margin-top: 0; }}        a {{ color: #60a5fa; text-decoration: none; }}        a:hover {{ text-decoration: underline; }}    </style></head><body>    <h1>📊 TS-Validator Metrics</h1>    <p><small>Generated: {datetime.now().strftime("%Y-%m-%d %H:%M:%S")}</small></p>        <div class="card">        <h3>🧪 D-Sandbox</h3>        <div class="metric"><span>Valid bindings:</span><strong>{valid}/{total}</strong></div>        <div class="metric"><span>Success rate:</span><strong>{pct:.1f}%</strong></div>        <div class="bar"><div class="fill" style="width:{pct}%"></div></div>        <div class="metric"><span>Avg friction:</span><strong>{friction}</strong></div>        <div class="metric"><span>ε_rec:</span><strong>{sb.get('epsilon_friction_recommended', 'N/A')}</strong></div>    </div>        <div class="card">        <h3>🎯 Layer 4: MetaCheck</h3>        <div class="metric"><span>ΔΓ_X:</span><strong>{delta:.4f}</strong></div>        <div class="metric"><span>Threshold (ε_X):</span><strong>0.25</strong></div>        <div class="metric">            <span>Status:</span>            <strong class="{status_class}">{status_text}</strong>        </div>        <div class="bar"><div class="fill" style="width:{min(100, delta/0.5*100)}%"></div></div>    </div>        <div class="card">        <h3>🔗 Quick Links</h3>        <p><a href="../output/layer1-3.log">Layer 1–3 Log</a> |           <a href="../output/sandbox.log">Sandbox Log</a> |           <a href="../output/layer4.log">Layer 4 Log</a></p>    </div></body></html>"""        with open(output_path, "w") as f:        f.write(html)    print(f"🌐 Dashboard saved: {os.path.abspath(output_path)}")if __name__ == "__main__":    parser = argparse.ArgumentParser()    parser.add_argument("--report", action="store_true", help="Print terminal report")    parser.add_argument("--html", action="store_true", help="Generate HTML dashboard")    args = parser.parse_args()        if not (args.report or args.html):        print("⚠️  Укажите флаг: --report, --html или оба (--report --html)")        sys.exit(1)            report = load_report()    if args.report:        print_terminal_dashboard(report)    if args.html:        generate_html_dashboard(report)